var hvPw = await import('playwright');
var hvBrowser;
try {
  hvBrowser = await hvPw.chromium.launch({ headless: true, args: ['--use-angle=swiftshader', '--enable-webgl', '--ignore-gpu-blocklist'] });
} catch (launchError) {
  hvBrowser = await hvPw.chromium.launch({ headless: true, channel: 'chrome', args: ['--use-angle=swiftshader', '--enable-webgl', '--ignore-gpu-blocklist'] });
}
var hvContext = await hvBrowser.newContext({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 1.5 });
var hvPage = await hvContext.newPage();
var hvErrors = [];
var hvFailedRequests = [];
hvPage.on('pageerror', error => hvErrors.push(String(error)));
hvPage.on('console', message => { if (message.type() === 'error') hvErrors.push('console: ' + message.text()); });
hvPage.on('requestfailed', request => hvFailedRequests.push(request.url() + ': ' + (request.failure()?.errorText || 'failed')));
var hvUrl = 'file:///Users/melvynx/Developer/experiments/benchmarks/benchmarks/air-conditioning-understanding/2026-07-15-codex-gpt-5-6-sol-2/index.html';
await hvPage.goto(hvUrl, { waitUntil: 'load', timeout: 45000 });
await hvPage.waitForFunction(() => document.body.dataset.ready === 'true' || document.body.dataset.ready === 'fallback', null, { timeout: 30000 });
var hvFailures = [];
var hvExpect = (condition, message) => { if (!condition) hvFailures.push(message); };
var hvInitial = await hvPage.evaluate(() => {
  const canvas = document.querySelector('canvas');
  const rect = canvas?.getBoundingClientRect();
  return {
    ready: document.body.dataset.ready,
    title: document.title,
    h1s: [...document.querySelectorAll('h1')].filter(el => el.getBoundingClientRect().width > 0).map(el => el.textContent.trim()),
    canvas: rect ? { width: rect.width, height: rect.height } : null,
    fallback: document.body.classList.contains('webgl-failed'),
    text: document.body.innerText
  };
});
hvExpect(hvInitial.ready === 'true', 'direct-file page did not reach ready state');
hvExpect(hvInitial.title === 'GPT-5.6 Sol', 'browser title mismatch');
hvExpect(hvInitial.h1s.length === 1 && hvInitial.h1s[0] === 'GPT-5.6 Sol', 'visible title mismatch');
hvExpect(hvInitial.canvas?.width > 1000 && hvInitial.canvas?.height > 700, 'canvas missing or undersized');
hvExpect(!hvInitial.fallback, 'fallback shown during normal load');
for (const term of ['Room air', 'Outdoor air', 'Refrigerant', 'Heat energy', 'Heat absorbed', 'Heat released', 'Indoor air']) {
  hvExpect(hvInitial.text.includes(term), 'missing visible term: ' + term);
}
var hvMatrixCases = [
  ['split', 'cooling', 'Indoor coil', 'Outdoor coil'],
  ['split', 'heating', 'Outdoor coil', 'Room-side coil'],
  ['monoblock', 'heating', 'Outdoor-air coil', 'Room-side coil'],
  ['monoblock', 'cooling', 'Room-side coil', 'Exhaust air coil']
];
var hvMatrixResults = [];
for (const [system, mode, absorbed, released] of hvMatrixCases) {
  await hvPage.click('button[data-action="system"][data-value="' + system + '"]');
  await hvPage.click('button[data-action="mode"][data-value="' + mode + '"]');
  await hvPage.waitForTimeout(130);
  const row = await hvPage.evaluate(() => ({
    system: document.body.dataset.system,
    mode: document.body.dataset.mode,
    absorbed: document.getElementById('absorbed-at').textContent.trim(),
    released: document.getElementById('released-at').textContent.trim(),
    labels: [...document.querySelectorAll('.scene-label:not(.is-hidden) strong')].map(el => el.textContent.trim())
  }));
  hvMatrixResults.push(row);
  hvExpect(row.system === system && row.mode === mode, system + '/' + mode + ' state mismatch');
  hvExpect(row.absorbed === absorbed, system + '/' + mode + ' absorbed mismatch');
  hvExpect(row.released === released, system + '/' + mode + ' released mismatch');
  if (system === 'monoblock') hvExpect(row.labels.includes('Outdoor intake') && row.labels.includes('Outdoor exhaust'), 'monoblock duct labels missing');
  if (system === 'split') hvExpect(row.labels.includes('Refrigerant lines'), 'split refrigerant line label missing');
}
await hvPage.click('#play-toggle');
await hvPage.waitForTimeout(180);
var hvPausedA = await hvPage.evaluate(() => ({ playing: document.body.dataset.playing, sim: Number(document.body.dataset.simTime || 0), label: document.getElementById('play-label').textContent.trim() }));
await hvPage.waitForTimeout(480);
var hvPausedB = await hvPage.evaluate(() => Number(document.body.dataset.simTime || 0));
hvExpect(hvPausedA.playing === 'false' && hvPausedA.label === 'Play', 'pause state failed');
hvExpect(Math.abs(hvPausedB - hvPausedA.sim) < 0.011, 'simulation moved while paused');
await hvPage.click('#play-toggle');
await hvPage.waitForTimeout(480);
var hvResumed = await hvPage.evaluate(() => ({ playing: document.body.dataset.playing, sim: Number(document.body.dataset.simTime || 0) }));
hvExpect(hvResumed.playing === 'true' && hvResumed.sim > hvPausedB, 'play state failed');
await hvPage.evaluate(() => {
  window.__hvacExperience.camera.position.set(-7, 3, 4);
  window.__hvacExperience.controls.target.set(2, 1, -2);
  window.__hvacExperience.controls.update();
});
await hvPage.click('#reset-view');
await hvPage.waitForTimeout(950);
var hvResetDistance = await hvPage.evaluate(() => window.__hvacExperience.camera.position.distanceTo(window.__hvacExperience.initialCamera));
hvExpect(hvResetDistance < 0.04, 'reset view failed');
await hvPage.click('#guide-close');
await hvPage.click('#replay-guide');
await hvPage.waitForTimeout(100);
var hvGuide = await hvPage.evaluate(() => ({ hidden: document.getElementById('tutorial').hidden, step: document.body.dataset.tourStep, title: document.getElementById('guide-title').textContent.trim() }));
hvExpect(!hvGuide.hidden && hvGuide.step === '1' && hvGuide.title === 'Air stays separate', 'guide replay failed');
await hvPage.setViewportSize({ width: 390, height: 844 });
await hvPage.waitForTimeout(280);
var hvMobile = await hvPage.evaluate(() => {
  const controls = [...document.querySelectorAll('button')].filter(el => {
    const style = getComputedStyle(el), r = el.getBoundingClientRect();
    return style.display !== 'none' && style.visibility !== 'hidden' && r.width > 0 && r.height > 0;
  }).map(el => {
    const r = el.getBoundingClientRect();
    return { label: el.getAttribute('aria-label') || el.textContent.trim(), left: r.left, top: r.top, right: r.right, bottom: r.bottom, width: r.width, height: r.height };
  });
  const canvasRect = document.querySelector('canvas').getBoundingClientRect();
  return { width: innerWidth, height: innerHeight, scrollWidth: document.documentElement.scrollWidth, controls, canvas: { width: canvasRect.width, height: canvasRect.height } };
});
hvExpect(hvMobile.scrollWidth <= hvMobile.width + 1, 'mobile horizontal overflow');
hvExpect(hvMobile.canvas.width === 390 && hvMobile.canvas.height === 844, 'mobile canvas resize failed');
for (const control of hvMobile.controls) {
  hvExpect(control.width >= 40 && control.height >= 40, 'small mobile target: ' + control.label);
  hvExpect(control.left >= -0.5 && control.top >= -0.5 && control.right <= hvMobile.width + 0.5 && control.bottom <= hvMobile.height + 0.5, 'mobile control out of bounds: ' + control.label);
}
await hvPage.click('button[data-action="system"][data-value="split"]');
await hvPage.click('button[data-action="mode"][data-value="heating"]');
await hvPage.click('#play-toggle');
await hvPage.click('#reset-view');
await hvPage.click('#replay-guide');
var hvReducedContext = await hvBrowser.newContext({ viewport: { width: 1024, height: 768 }, reducedMotion: 'reduce' });
var hvReducedPage = await hvReducedContext.newPage();
await hvReducedPage.goto(hvUrl, { waitUntil: 'load', timeout: 45000 });
await hvReducedPage.waitForFunction(() => document.body.dataset.ready === 'true' || document.body.dataset.ready === 'fallback', null, { timeout: 30000 });
var hvReduced = await hvReducedPage.evaluate(() => ({ ready: document.body.dataset.ready, motion: document.body.dataset.motion, playing: document.body.dataset.playing }));
hvExpect(hvReduced.ready === 'true' && hvReduced.motion === 'reduced' && hvReduced.playing === 'false', 'reduced-motion behavior failed');
var hvFallbackContext = await hvBrowser.newContext({ viewport: { width: 1024, height: 768 } });
var hvFallbackPage = await hvFallbackContext.newPage();
await hvFallbackPage.addInitScript(() => {
  const original = HTMLCanvasElement.prototype.getContext;
  HTMLCanvasElement.prototype.getContext = function(type, ...args) {
    if (/^webgl/.test(type)) return null;
    return original.call(this, type, ...args);
  };
});
await hvFallbackPage.goto(hvUrl, { waitUntil: 'load', timeout: 45000 });
await hvFallbackPage.waitForFunction(() => document.body.dataset.ready === 'fallback', null, { timeout: 15000 });
var hvFallback = await hvFallbackPage.evaluate(() => ({ ready: document.body.dataset.ready, title: document.title, h1: document.querySelector('h1').textContent.trim(), visible: getComputedStyle(document.getElementById('webgl-fallback')).display !== 'none' }));
hvExpect(hvFallback.ready === 'fallback' && hvFallback.visible && hvFallback.title === 'GPT-5.6 Sol' && hvFallback.h1 === 'GPT-5.6 Sol', 'WebGL fallback failed');
hvExpect(hvErrors.length === 0, 'page errors: ' + hvErrors.join(' | '));
hvExpect(hvFailedRequests.length === 0, 'failed requests: ' + hvFailedRequests.join(' | '));
var hvSummary = {
  ok: hvFailures.length === 0,
  failures: hvFailures,
  initial: { ready: hvInitial.ready, title: hvInitial.title, canvas: hvInitial.canvas },
  matrix: hvMatrixResults.map(r => ({ system: r.system, mode: r.mode, absorbed: r.absorbed, released: r.released })),
  transport: { paused: hvPausedA, pausedAfter: hvPausedB, resumed: hvResumed, resetDistance: hvResetDistance },
  guide: hvGuide,
  mobile: { scrollWidth: hvMobile.scrollWidth, width: hvMobile.width, canvas: hvMobile.canvas, controls: hvMobile.controls.length },
  reducedMotion: hvReduced,
  fallback: hvFallback,
  pageErrors: hvErrors,
  failedRequests: hvFailedRequests
};
await hvBrowser.close();
nodeRepl.write(hvSummary);

